export const MONUMENTS = JSON.parse("[{\"id\":\"n1352565268\",\"kind\":\"memorial\",\"sub\":\"stele\",\"name\":\"памятник Человеку-невидимке (ранее Александру II)\",\"x\":-2737,\"z\":1655,\"material\":\"stone\"},{\"id\":\"n1107412254\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Г. В. Плеханов\",\"x\":-1826.7,\"z\":1686.3,\"subject\":\"Q182905\",\"inscription\":\"1856-1918\"},{\"id\":\"n5752062653\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. Д. Зелинскому\",\"x\":-1882.1,\"z\":1654.3,\"subject\":\"Q435709\",\"inscription\":\"Здесь в 1915 году выдающийся ученый Николай Дмитриевич Зелинский изобрел угольный противогаз\"},{\"id\":\"n6517079213\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. И. Менделееву\",\"x\":-1845.7,\"z\":1646.2,\"subject\":\"Q9106\",\"inscription\":\"Здесь жил и работал в 1863–1872 годы великий русский учёный, создатель периодической системы элементов Дмитрий Иванович Менделеев (1834–1907)\"},{\"id\":\"n6517079214\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. К. Чернову\",\"x\":-1845.8,\"z\":1641.4,\"subject\":\"Q738334\",\"inscription\":\"Здесь в 1859–1866 годы работал выдающийся русский учёный, основоположник теории металлургических процессов Дмитрий Константинович Чернов (1839–1921)\"},{\"id\":\"n6517079216\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. М. Кржижановскому\",\"x\":-1843,\"z\":1655.8,\"subject\":\"Q944478\",\"inscription\":\"Здесь с 1889 г. по 1894 г. учился и начал свою революционную работу в марксистском кружке студентов-технологов старейший деятель революционного движения, крупный учёный-энергетик Глеб Максимилианович Кржижановский\"},{\"id\":\"n6517079218\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-1797.2,\"z\":1678.8,\"subject\":\"Q1394\",\"inscription\":\"В 1905–1906 гг. В.И. Ленин неоднократно выступал в здании Технологического института на партийных собраниях Петербургской социал-демократической организации по вопросам тактики большевиков в буржуазно-демократической революции\"},{\"id\":\"n6517079219\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. П. Горбунову\",\"x\":-1782.6,\"z\":1675.5,\"subject\":\"Q4811867\",\"inscription\":\"Здесь, в Технологическом институте, в 1910–1917 гг. учился Николай Петрович Горбунов, советский государственный деятель, один из организаторов науки, академик\"},{\"id\":\"n6517079220\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. Варыньскому\",\"x\":-1774.4,\"z\":1669.7,\"subject\":\"Q1875503\",\"inscription\":\"Здесь, в Петербургском технологическом институте, в 1874–1875 годах учился Людвик Варыньский — деятель социалистического движения, основатель польской партии «Пролетариат» (1882). Погиб в Шлиссельбургской крепости в 1889 году.\"},{\"id\":\"n6570418417\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-3045.2,\"z\":1706.3},{\"id\":\"n6570418418\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-3001.6,\"z\":1686},{\"id\":\"n11677773835\",\"kind\":\"artwork\",\"sub\":\"graffiti\",\"name\":\"Алиса в стране чудес\",\"x\":-2989,\"z\":1642.4}]");
